function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listPeriodicAllocationVouchers(
  query: Record<string, string | number | boolean>,
): Promise<PeriodicAllocationVoucherListItem[]> {
  const res = await apiClient.get<BffResponse<PeriodicAllocationVoucherListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getPeriodicAllocationVoucher(sttRec: string): Promise<PeriodicAllocationVoucher> {
  const res = await apiClient.get<BffResponse<PeriodicAllocationVoucher>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function getPeriodicAllocationAccountFlags(
  codes: string,
): Promise<{ items: PeriodicAllocationAccountFlag[] }> {
  const res = await apiClient.get<BffResponse<{ items: PeriodicAllocationAccountFlag[] }>>(
    withQuery(`${BASE}/account-flags`, { codes }),
  );
  return unwrap(res);
}

export async function createPeriodicAllocationVoucher(
  body: PeriodicAllocationWrite,
): Promise<PeriodicAllocationVoucher> {
  const res = await apiClient.post<BffResponse<PeriodicAllocationVoucher>>(BASE, body);
  return unwrap(res);
}

export async function updatePeriodicAllocationVoucher(
  sttRec: string,
  body: PeriodicAllocationWrite,
): Promise<PeriodicAllocationVoucher> {
  const res = await apiClient.put<BffResponse<PeriodicAllocationVoucher>>(
    `${BASE}/${encodeURIComponent(sttRec)}`,
    body,
  );
  return unwrap(res);
}

export async function unpostPeriodicAllocationVoucher(sttRec: string): Promise<PeriodicAllocationVoucher> {
  const res = await apiClient.post<BffResponse<PeriodicAllocationVoucher>>(
    `${BASE}/${encodeURIComponent(sttRec)}/unpost`,
  );
  return unwrap(res);
}
