import React, { useCallback, useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select } from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  listPeriodicAllocationVouchers,
  type PeriodicAllocationVoucherListItem,
} from '../../../services/kt/periodicAllocationVouchers';
import df from '../../../styles/documentForm.module.css';

interface SearchState {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maGd: string;
  maPost: string;
  maQuyen: string;
  tkNoH: string;
  tkCoH: string;
  tien1: string;
  tien2: string;
  maKhN: string;
  maKhC: string;
  maVv: string;
  maHd: string;
  maPhi: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
}

const emptySearch = (): SearchState => ({
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maGd: '1',
  maPost: '9',
  maQuyen: '',
  tkNoH: '',
  tkCoH: '',
  tien1: '',
  tien2: '',
  maKhN: '',
  maKhC: '',
  maVv: '',
  maHd: '',
  maPhi: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
});

function formatDate(value: string | null | undefined): string {
  if (!value) return '';
  try {
    const parsed = parseISO(value);
    if (Number.isNaN(parsed.getTime())) return value;
    return format(parsed, 'dd/MM/yyyy');
  } catch {
    return value;
  }
}

function amountQuery(raw: string): number | undefined {
  const text = raw.trim();
  if (!text) return undefined;
  const value = Number(text);
  if (!Number.isFinite(value) || value === 0) return undefined;
  return value;
}

function buildSearchQuery(search: SearchState): Record<string, string | number | boolean> {
  const query: Record<string, string | number | boolean> = { maGd: '1', maPost: '9' };
  const textKeys: (keyof SearchState)[] = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maQuyen', 'tkNoH', 'tkCoH',
    'maKhN', 'maKhC', 'maVv', 'maHd', 'maPhi', 'maSp', 'maKu', 'maTtln',
    'maTtcp', 'maBp', 'maHs', 'maCd', 'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = String(search[key]).trim();
    if (value) query[key] = value;
  });
  const tien1 = amountQuery(search.tien1);
  const tien2 = amountQuery(search.tien2);
  if (tien1 !== undefined) query.tien1 = tien1;
  if (tien2 !== undefined) query.tien2 = tien2;
  if (search.locNsd) query.locNsd = true;
  return query;
}

const Pb6ListPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const [search, setSearch] = useState<SearchState>(emptySearch);
  const [filtering, setFiltering] = useState(false);
  const [items, setItems] = useState<PeriodicAllocationVoucherListItem[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const loadOpen = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const rows = await listPeriodicAllocationVouchers({ loadTop: 0 });
      setItems(rows);
      setSelectedSttRec('');
    } catch (err) {
      setItems([]);
      setError(getApiErrorMessage(err, 'Không tải được danh sách bút toán phân bổ định kỳ'));
    } finally {
      setLoading(false);
    }
  }, []);

  const loadSearch = useCallback(async (current: SearchState) => {
    setLoading(true);
    setError('');
    try {
      const rows = await listPeriodicAllocationVouchers(buildSearchQuery(current));
      setItems(rows);
      setSelectedSttRec('');
    } catch (err) {
      setItems([]);
      setError(getApiErrorMessage(err, 'Không tải được danh sách bút toán phân bổ định kỳ'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadOpen();
  }, [loadOpen]);

  const onSearch = () => {
    setFiltering(true);
    void loadSearch(search);
  };

  const onRefresh = () => {
    if (filtering) void loadSearch(search);
    else void loadOpen();
  };

  const onEnter = (event: React.KeyboardEvent) => {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    onSearch();
  };

  const setText = (key: keyof SearchState) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(prev => ({ ...prev, [key]: event.target.value }));
  };

  const noSelection = !selectedSttRec;

  return (
    <div className={df.page} data-testid="ct-pb6-list">
      <h1 data-testid="ct-pb6-title">Bút toán phân bổ định kỳ</h1>
      <div className={df.headerActions}>
        <Button variant="secondary" data-testid="ct-pb6-toolbar-refresh-btn" onClick={onRefresh}>Làm mới</Button>
        <Button variant="primary" data-testid="ct-pb6-toolbar-add-btn" onClick={() => navigate('/kt/pb6/them')}>Thêm</Button>
        <Button variant="secondary" data-testid="ct-pb6-toolbar-edit-btn" disabled={noSelection} onClick={() => navigate(`/kt/pb6/${selectedSttRec}`)}>Sửa</Button>
        <Button variant="secondary" data-testid="ct-pb6-toolbar-view-btn" disabled={noSelection} onClick={() => navigate(`/kt/pb6/${selectedSttRec}?mode=view`)}>Xem</Button>
        <Button variant="secondary" data-testid="ct-pb6-toolbar-copy-btn" disabled={noSelection} onClick={() => navigate(`/kt/pb6/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}>Sao chép</Button>
      </div>

      <section className={df.section} data-testid="ct-pb6-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <div>
            <label className={df.label}>Ngày C.từ từ</label>
            <Input type="date" data-testid="ct-pb6-search-ngayCt1" value={search.ngayCt1} onChange={setText('ngayCt1')} />
          </div>
          <div>
            <label className={df.label}>Ngày C.từ đến</label>
            <Input type="date" data-testid="ct-pb6-search-ngayCt2" value={search.ngayCt2} onChange={setText('ngayCt2')} />
          </div>
          <div>
            <label className={df.label}>Số C.từ từ</label>
            <Input maxLength={30} data-testid="ct-pb6-search-soCt1" value={search.soCt1} onChange={setText('soCt1')} />
          </div>
          <div>
            <label className={df.label}>Số C.từ đến</label>
            <Input maxLength={30} data-testid="ct-pb6-search-soCt2" value={search.soCt2} onChange={setText('soCt2')} />
          </div>
          <div>
            <Select
              label="Loại giao dịch"
              data-testid="ct-pb6-search-maGd"
              value={search.maGd}
              options={[{ value: '1', label: 'Phiếu phân bổ định kỳ' }]}
              onChange={event => setSearch(prev => ({ ...prev, maGd: event.target.value }))}
            />
          </div>
        </div>
        <Button variant="primary" data-testid="ct-pb6-search-btn" onClick={onSearch}>Tìm</Button>
      </section>

      <section className={df.section} data-testid="ct-pb6-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <div>
            <Select
              label="Trạng thái"
              data-testid="ct-pb6-search-maPost"
              value={search.maPost}
              options={[{ value: '9', label: 'Hạch toán sổ cái' }]}
              onChange={event => setSearch(prev => ({ ...prev, maPost: event.target.value }))}
            />
          </div>
          <Field label="Quyền" testId="ct-pb6-search-maQuyen" value={search.maQuyen} onChange={setText('maQuyen')} />
          <Field label="Tk nợ" testId="ct-pb6-search-tkNoH" value={search.tkNoH} onChange={setText('tkNoH')} />
          <Field label="Tk có" testId="ct-pb6-search-tkCoH" value={search.tkCoH} onChange={setText('tkCoH')} />
          <Field label="Giá trị phân bổ từ" testId="ct-pb6-search-tien1" value={search.tien1} onChange={setText('tien1')} inputMode="decimal" />
          <Field label="Giá trị phân bổ đến" testId="ct-pb6-search-tien2" value={search.tien2} onChange={setText('tien2')} inputMode="decimal" />
          <Field label="Đ.Tượng nợ" testId="ct-pb6-search-maKhN" value={search.maKhN} onChange={setText('maKhN')} />
          <Field label="Đ.Tượng có" testId="ct-pb6-search-maKhC" value={search.maKhC} onChange={setText('maKhC')} />
          <Field label="V.Việc" testId="ct-pb6-search-maVv" value={search.maVv} onChange={setText('maVv')} />
          <Field label="Hợp đồng" testId="ct-pb6-search-maHd" value={search.maHd} onChange={setText('maHd')} />
          <Field label="khoản mục" testId="ct-pb6-search-maPhi" value={search.maPhi} onChange={setText('maPhi')} />
          <Field label="Sản phẩm" testId="ct-pb6-search-maSp" value={search.maSp} onChange={setText('maSp')} />
          <Field label="Khế ước" testId="ct-pb6-search-maKu" value={search.maKu} onChange={setText('maKu')} />
          <Field label="Trung tâm lợi nhuận" testId="ct-pb6-search-maTtln" value={search.maTtln} onChange={setText('maTtln')} />
          <Field label="Trung tâm chi phí" testId="ct-pb6-search-maTtcp" value={search.maTtcp} onChange={setText('maTtcp')} />
          <Field label="Phòng ban" testId="ct-pb6-search-maBp" value={search.maBp} onChange={setText('maBp')} />
          <Field label="Nhân sự" testId="ct-pb6-search-maHs" value={search.maHs} onChange={setText('maHs')} />
          <Field label="Công đoạn" testId="ct-pb6-search-maCd" value={search.maCd} onChange={setText('maCd')} />
          <Field label="Mã tự do 1" testId="ct-pb6-search-maTd1" value={search.maTd1} onChange={setText('maTd1')} />
          <Field label="Mã tự do 2" testId="ct-pb6-search-maTd2" value={search.maTd2} onChange={setText('maTd2')} />
          <Field label="Mã tự do 3" testId="ct-pb6-search-maTd3" value={search.maTd3} onChange={setText('maTd3')} />
          <Field label="Mã tự do 4" testId="ct-pb6-search-maTd4" value={search.maTd4} onChange={setText('maTd4')} />
          <Field label="Mã tự do 5" testId="ct-pb6-search-maTd5" value={search.maTd5} onChange={setText('maTd5')} />
          <div>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-pb6-search-locNsd"
              checked={search.locNsd}
              onChange={event => setSearch(prev => ({ ...prev, locNsd: event.target.checked }))}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}

      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-pb6-grid">
          <thead>
            <tr>
              <th>Số C.từ</th>
              <th>Ngày C.từ</th>
              <th>Ngày bắt đầu</th>
              <th>Số kỳ</th>
              <th>Giá trị phân bổ</th>
              <th>Giá trị phân bổ NT</th>
              <th>Ngoại tệ</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                aria-selected={row.sttRec === selectedSttRec}
                style={row.sttRec === selectedSttRec ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{formatDate(row.ngayCt)}</td>
                <td>{formatDate(row.ngayPb)}</td>
                <td>{row.soKyPb}</td>
                <td>{row.tTt}</td>
                <td>{row.tTtNt}</td>
                <td>{row.maNt}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {items.length === 0 && !loading ? (
        <div>{filtering ? 'Không tìm thấy bút toán phân bổ định kỳ' : 'Không có bút toán phân bổ định kỳ'}</div>
      ) : null}
    </div>
  );
};

const Field: React.FC<{
  label: string;
  testId: string;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  inputMode?: 'decimal';
}> = ({ label, testId, value, onChange, inputMode }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input maxLength={inputMode ? undefined : 30} inputMode={inputMode} data-testid={testId} value={value} onChange={onChange} />
  </div>
);

export default Pb6ListPage;
